Running command: cd /workspace && cat > analysis.json <<'JSON'
{
  "sample_id": "osv_ossfuzz_OSV-2026-514",
  "fine_trace": [
    {
      "step": 1,
      "file": "format.c",
      "function": "format_expand1",
      "line": 5457,
      "var": "fmt",
      "code": "while (*fmt != '\\0') {",
      "role": "source",
      "note": "The loop processes bytes from the caller supplied format string; the input byte '#' enters this parser through fmt."
    },
    {
      "step": 2,
      "file": "format.c",
      "function": "format_expand1",
      "line": 5469,
      "var": "fmt",
      "code": "ch = (u_char)*fmt++;",
      "role": "root_cause",
      "note": "After consuming a '#' at the end of the string, the parser reads the terminating NUL as ch and increments fmt past the end instead of first requiring another character after '#'."
    },
    {
      "step": 3,
      "file": "format.c",
      "function": "format_expand1",
      "line": 5457,
      "var": "*fmt",
      "code": "while (*fmt != '\\0') {",
      "role": "sink",
      "note": "The default case continues to the loop condition with fmt one byte past the NUL terminator, causing a one byte heap-buffer-overflow read."
    }
  ],
  "vuln_logic": {
    "source": {
      "file": "format.c",
      "function": "format_expand1",
      "line": 5457,
      "operands": ["fmt"]
    },
    "root_cause": {
      "file": "format.c",
      "function": "format_expand1",
      "line": 5469,
      "operands": ["*fmt", "'\\0'"],
      "relation": {"op": "ne", "left": "*fmt", "right": "'\\0'"}
    },
    "sink": {
      "file": "format.c",
      "function": "format_expand1",
      "line": 5457,
      "operands": ["fmt", "fmt + strlen(fmt)"],
      "relation": {"op": "le", "left": "fmt", "right": "fmt + strlen(fmt)"}
    },
    "propagation": [
      {
        "from": {"file": "format.c", "function": "format_expand1", "line": 5457, "operands": ["fmt"]},
        "to": {"file": "format.c", "function": "format_expand1", "line": 5457, "operands": ["*fmt"]},
        "type": "data",
        "via": ["fmt++", "ch"]
      }
    ]
  }
}
